use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:1.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_volume_roc",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,v:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{let p=x[0]as usize;Ok(Box::new(I{p,v:RingVec::new(p+1)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{self.v.push(t.qty);if self.v.len()!=self.p+1{return None}let old=self.v.get(0).unwrap();Some(if old==0.{0.}else{(t.qty-old)/old*100.})}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(q:f64)->Trade{Trade{price:1.,qty:q,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn roc(){let mut i=create(&[1.]).unwrap();i.on_trade(&t(2.));assert_eq!(i.on_trade(&t(4.)),Some(100.));}}
